mapper.select:
select scope_id, notice_id, scope_type, target_id, create_time
from sys_notice_scope
where notice_id = #{noticeId}

SELECT DISTINCT ns.notice_id
FROM sys_notice_scope ns
WHERE (
    -- 个人范围
    (ns.scope_type = '3' AND ns.target_id = #{userId})
    OR
    -- 部门范围（包含当前部门及其所有上级部门）
    (ns.scope_type = '1' AND (
        ns.target_id = (
            SELECT dept_id FROM sys_user WHERE user_id = #{userId}
        )
        OR
        FIND_IN_SET(ns.target_id, (
            SELECT ancestors FROM sys_dept WHERE dept_id = (
                SELECT dept_id FROM sys_user WHERE user_id = #{userId}
            )
        )) > 0
    ))
    OR
    -- 岗位范围
    (ns.scope_type = '2' AND ns.target_id IN (
        SELECT post_id FROM sys_user_post WHERE user_id = #{userId}
    ))
    OR
    -- 角色范围
    (ns.scope_type = '2' AND ns.target_id IN (
        SELECT role_id FROM sys_user_role WHERE user_id = #{userId}
    ))
)
